fn count_and_max(values: &Vec<Int>) -> (Int, Int) {
    let mut count = 0;
    let mut max = i32::MIN;
    for &x in values {
        if x > 0 {
            count = count + 1;
        }
        if x > max {
            max = x;
        }
    }
    (count, max)
}

